const e={"home.about.card.list.0":"Raziskava in validacija smeri izdelka (v teku)","home.about.card.list.1":"Razvoj osnovnih zmogljivosti: Inženirski sistem / Zmožnosti podatkov in storitev / Infrastruktura","home.about.card.list.2":"Prototipiranje in hitra iteracija: Od ideje do uporabne različice","home.about.card.list.3":"Usklajenost in varnost: Poudarjanje varnosti podatkov in zaščite zasebnosti","home.about.card.note":"Ker je obseg poslovanja še vedno v raziskovalni fazi...","home.about.card.title":"Kaj počnemo?","home.about.desc.0":"Smo podjetje za omrežno tehnologijo, osredotočeno na lastno raziskovanje...","home.about.desc.1":"Trenutno poslovno področje je še vedno v nenehnem raziskovanju...","home.about.hl.0.num":"Samoizdelan prvi","home.about.hl.0.text":"Nenehna naložba v lastne izdelke in poslovanje.","home.about.hl.1.num":"Stalna iteracija","home.about.hl.1.text":"Poudarite kakovost inženiringa, vzdržljivost in razširljivost.","home.about.hl.2.num":"Neprestano raziskovanje","home.about.hl.2.text":"Dinamična evolucija poslovnih smernic postopoma oblikuje jasne meje.","home.about.title":"O nas","home.brand.en":"TreeHouse Tech · Šanghaj","home.common.city":"Šanghaj · ŠANGHAJ","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"Če nas želite kontaktirati, prosimo, da se obrnete na nas preko e-pošte...","home.contact.label.city":"Mesto","home.contact.label.company":"Ime podjetja","home.contact.label.email":"E-pošta","home.contact.title":"Kontaktni podatki","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"O nas","home.footer.links.contact":"Kontaktirajte nas","home.footer.links.home":"Domov","home.footer.slogan":"Osredotočite se na neodvisno raziskovanje in razvoj · Neprestano raziskovanje · Stabilna iteracija","home.hero.cta.about":"Izvedite več o nas →","home.hero.cta.contact":"Kontaktni podatki","home.hero.desc":"Smo podjetje za omrežno tehnologijo, osredotočeno na lastno raziskovanje. Nenehno raziskujemo dragocene smeri izdelkov in poti tehnične izvedbe, z namenom dolgoročnih iteracij in stabilne dostave.","home.hero.glass":'Raziskovanje smeri → Izvedba inženiringa → Izpopolnitev izdelka <span class="dot"></span> Dolgoročnost / Stabilna dostava',"home.hero.meta.0.label":"Osredotočeno na izdelek in inženiring","home.hero.meta.0.num":"Samo-razvito","home.hero.meta.1.label":"Neprestano iteriranje in izpopolnjevanje","home.hero.meta.1.num":"Dolgoročno","home.hero.meta.2.label":"Poudarite kakovost in skladnost","home.hero.meta.2.num":"Stabilno","home.hero.mini.foot":"* Trenutna uradna spletna stran je osnovna predstavitvena stran, vsebina pa se bo nenehno posodabljala, ko se bo poslovanje razvijalo.","home.hero.mini.head":"Nasvet","home.hero.mini.main":"Neprestano raziskovanje poslovnih smeri","home.hero.mini.stats.0.k":"Osredotočenost","home.hero.mini.stats.0.v":"Izdelek, ki smo ga razvili sami","home.hero.mini.stats.1.k":"Oblika","home.hero.mini.stats.1.v":"Postopoma razjasnite","home.hero.mini.stats.2.k":"Ritem","home.hero.mini.stats.2.v":"Iterativni napredek","home.hero.mini.stats.3.k":"Cilj","home.hero.mini.stats.3.v":"Trajnostna rast","home.hero.title":'Osredotočanje na <span class="accent"> neodvisno raziskovanje in razvoj </span> ter raziskovanje izdelkov',"home.html.lang":"sl","home.meta.description":"上海树下小屋网络科技有限公司 - Osredotočeni na neodvisno raziskovanje in raziskovanje izdelkov","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"O nas","home.nav.contact":"Kontaktirajte nas","home.nav.home":"Domov","home.nav.toggle":"Razširi meni","home.noscript":"Ta stran zahteva JavaScript za popolno interaktivno izkušnjo (navigacijski meni, učinki pomikanja itd.).","nav.apps":"Center aplikacij","nav.support":"Podpora","apps.hero.eyebrow":"sxxw.site · Center za podporo aplikacij","apps.hero.title":"Vsaka aplikacija ima jasna navodila in meje podatkov, ki jih nadzorujete vi.","apps.hero.desc":"Tukaj najdete predstavitve izdelkov, vodnike za začetek, pravilnike o zasebnosti, pogoje in tehnično podporo. Preberite razdelek za platformo, ki jo dejansko uporabljate.","apps.card.cta":"Ogled aplikacije","apps.memoria.desc":"Spremljajte rojstne dneve, obletnice in odštevanja. Različica za iOS podpira izbirno zasebno sinhronizacijo iCloud; izdaja Memoria v Huawei AppGallery deluje v celoti v napravi.","apps.memoria.tag":"Obletnice · Opomniki","apps.timetrails.desc":"Beleženje sledi GPS z zasebnostjo na prvem mestu: samodejno zabeleži izlete, vadbe in potovanja, izriše vaše stopinje na zemljevidu in osvetli mesta, ki ste jih obiskali. Sledi privzeto ostanejo v napravi z izbirno zasebno varnostno kopijo iCloud.","apps.timetrails.tag":"Sledi GPS · Poti","apps.traceapp.desc":"Beleži pot, razdaljo, hitrost in tempo. Brez računa, brez vgrajenih oglasov ali analitike tretjih oseb.","apps.traceapp.tag":"Poti · Statistika","apps.footer.slogan":"Izdelki · Vodniki · Zasebnost in podpora","support.brand":"Podpora","support.hero.eyebrow":"sxxw.site · Center za podporo","support.hero.title":"Stopite v stik s TreeHouse na način, ki vam najbolj ustreza.","support.hero.desc":"Vsi uradni kanali podpore za aplikacije TreeHouse na enem mestu: povratne informacije, ocene v trgovinah z aplikacijami in uradne skupnostne skupine. Najprej lokalno, brez oglasov, brez sledenja tretjih oseb.","support.g1.title":"Povratne informacije","support.g1.note":"Naleteli ste na težavo ali imate idejo? Obrnite se na nas na kateri koli način spodaj — preberemo vsako sporočilo.","support.g1.feedback.name":"Povratne informacije v aplikaciji","support.g1.feedback.desc":"Pošljite neposredno v vsaki aplikaciji; vaša različica, naprava in podatki o sistemu se priložijo samodejno, da lahko hitreje preučimo.","support.g1.feedback.cta":"Ogled aplikacij","support.g1.email.name":"Pošlji e-pošto","support.g1.email.desc":"Za uradne zahteve ter vprašanja zasebnosti ali računa e-pošta prejme obsežnejši odgovor.","support.g1.email.cta":"Pošlji e-pošto","support.g2.title":"Ocenite aplikacije (vsako posebej)","support.g2.note":"Če so vam všeč, pustite oceno v trgovini, ki jo uporabljate — vidimo jo in odgovorimo. Tapnite tisto, ki ustreza vaši aplikaciji.","support.g2.cta.write":"Napišite oceno","support.g2.cta.goto":"Pojdi na oceno","support.g2.memoria.huawei.platform":"HarmonyOS · Naprave Huawei","support.g3.title":"Skupine WeChat · QQ · Telegram","support.g3.note":"Pridružite se našim uradnim skupinam za novice in pomoč drugih uporabnikov: WeChat / QQ na Kitajskem, Telegram drugod.","support.g3.wechat.name":"Skupina WeChat","support.g3.wechat.desc":"Vsakodnevno klepetanje in pomoč. Ko se skupina napolni, objavimo novo kodo QR.","support.g3.qq.name":"Skupina QQ","support.g3.qq.desc":"Za uporabnike na Kitajskem; visoka omejitev članov.","support.g3.tg.name":"Skupina Telegram","support.g3.tg.desc":"Klepet in vprašanja za mednarodne uporabnike.","support.g3.join":"Pridruži se","support.pending":"Kmalu na voljo","support.foot":"Ne najdete pravega kanala? Pišite na house@sxxw.site in oglasili se vam bomo.","support.footer.slogan":"Povratne informacije · Ocene v trgovinah · Skupnostne skupine","mem.ios.tagline":"Zabeležite rojstne dneve, obletnice in pomembne dni — naj bo čas viden z nežnostjo.","mem.ios.desc":"Rojstne dneve, obletnice, obletnice zveze, praznike in dneve, ki so vam pri srcu, shranite na eno mirno mesto. Odštevajte, koliko dni je še ostalo, in štejte navzgor, koliko jih je že minilo.","mem.ios.feat.0":"Rojstni dnevi, obletnice, prazniki in lastni dogodki","mem.ios.feat.1":"Datumi po gregorijanskem in kitajskem luninem koledarju","mem.ios.feat.2":"Odštevanje, štetje navzgor in potek življenja","mem.ios.feat.3":"Lokalni opomniki, pripomočki na začetnem in zaklenjenem zaslonu","mem.ios.feat.4":"Hiter pregled na Apple Watch","mem.ios.feat.5":"Izbirna zasebna sinhronizacija prek iCloud","mem.ios.guide.0.t":"Ustvarite prvi vnos","mem.ios.guide.0.b":"Ko odprete aplikacijo, izberite Dodaj in vnesite ime, datum in opombo, ki jo želite ohraniti. Po potrebi izberite rojstni dan, obletnico, praznik ali lasten dogodek.","mem.ios.guide.1.t":"Izberite pravilo datuma","mem.ios.guide.1.b":"Za rojstne dneve in obletnice lahko uporabite gregorijanski ali lunin koledar. Pri vnosih po luninem koledarju se naslednji datum izračuna po pravilu.","mem.ios.guide.2.t":"Nastavite opomnike","mem.ios.guide.2.b":"Za pomembne dni vklopite lokalna obvestila in izberite čas opomnika na dan sam ali vnaprej. Če je dovoljenje za obvestila izklopljeno, vas aplikacija pozove, da odprete sistemske nastavitve.","mem.ios.guide.3.t":"Vklopite sinhronizacijo po potrebi","mem.ios.guide.3.b":"Za sinhronizacijo med lastnimi iPhone, iPad in Apple Watch vklopite sinhronizacijo, ko ste prijavljeni v iCloud. Podatki gredo v vašo zasebno zbirko CloudKit; razvijalci jih ne morejo brati.","mem.hm.tagline":"Rojstne dneve, obletnice in pomembne dni zabeležite lokalno v napravi.","mem.hm.desc":"To je lokalna različica aplikacije Memoria za HarmonyOS. Brez računa, brez omrežja, brez sinhronizacije v oblaku; podatki ostanejo le v peskovniku aplikacije v vaši napravi.","mem.hm.feat.0":"Rojstni dnevi, obletnice, prazniki in lastni dogodki","mem.hm.feat.1":"Datumi po gregorijanskem in kitajskem luninem koledarju","mem.hm.feat.2":"Odštevanje, štetje navzgor in potek življenja","mem.hm.feat.3":"Lokalni opomniki","mem.hm.feat.4":"Obnovitev iz koša in dokončen izbris","mem.hm.feat.5":"Brez računa, brez oglasov, brez omrežnih zahtev","mem.hm.guide.0.t":"Ustvarite novo obletnico","mem.hm.guide.0.b":"Odprite stran z obletnicami, izberite Novo in vnesite ime, datum, vrsto in opombo. Po potrebi izberite datum po luninem koledarju.","mem.hm.guide.1.t":"Potrdite naslednji datum","mem.hm.guide.1.b":"Po shranjevanju aplikacija prikaže naslednji datum glede na datum in pravilo ponavljanja. Vnosi po luninem koledarju se pretvorijo po ustreznem pravilu.","mem.hm.guide.2.t":"Nastavite lokalni opomnik","mem.hm.guide.2.b":"V vnosu izberite čas opomnika in število dni vnaprej. Ob prvi nastavitvi opomnika dovolite sistemska obvestila; izklop dovoljenja vpliva le na opomnike, ne na beleženje ali pregledovanje.","mem.hm.guide.3.t":"Upravljajte lokalne podatke","mem.hm.guide.3.b":"Izbrisani vnosi gredo najprej v koš, kjer jih lahko obnovite ali dokončno izbrišete. Odstranitev aplikacije izbriše podatke v tej napravi; ker ni varnostne kopije v oblaku, jih po zamenjavi naprave ali odstranitvi ni mogoče obnoviti.","tt.tagline":"Beleženje sledi GPS — ohranite prehojeno pot v svojem času.","tt.desc":"TimeTrails je aplikacija za beleženje sledi GPS, ki na prvo mesto postavlja zasebnost. Samodejno beleži poti, tek, kolesarjenje, pohode in vožnje z avtomobilom, sledi živo prikaže na zemljevidu in osvetli obiskana mesta. Brez registracije računa, brez oglasov ali sledenja tretjih oseb; podatki o sledeh privzeto ostanejo le v vaši napravi.","tt.feat.0":"Samodejno beleži dnevno gibanje in razdaljo","tt.feat.1":"Ustvarja dnevne povzetke sledi in dejavnosti po lokalnem času","tt.feat.2":"Obudite obiskane kraje z odkrivanjem megle","tt.feat.3":"Prepozna vrsto dejavnosti: hojo, kolesarjenje, vožnjo in drugo","tt.feat.4":"Izbirni uvoz fotografij za ohranjanje spominov na pot","tt.feat.5":"Izbirna zasebna varnostna kopija zbirke iCloud in obnovitev ob zamenjavi naprave","tt.guide.0.t":"Izberite dovoljenje za lokacijo","tt.guide.0.b":"Za neprekinjeno beleženje v ozadju v sistemskem pozivu dovolite lokacijo »Vedno« in »Natančno lokacijo«. To lahko kadar koli spremenite v sistemskih nastavitvah.","tt.guide.1.t":"Začnite beleženje","tt.guide.1.b":"Ob prvem vstopu vklopite beleženje. V aplikaciji lahko vedno začasno ustavite ali nadaljujete — nadzor je v vaših rokah.","tt.guide.2.t":"Oglejte si dnevne sledi","tt.guide.2.b":"V koledarju ali na zemljevidu preglejte pot, razdaljo, postanke in povzetek dejavnosti vsakega dne.","tt.guide.3.t":"Vklopite varnostno kopijo po potrebi","tt.guide.3.b":"Če potrebujete obnovitev ob zamenjavi naprave ali sinhronizacijo med več napravami, sami vklopite varnostno kopijo podatkov iCloud v nastavitvah; privzeto je izklopljena.","trace.tagline":"Zabeležite vsako pot in nadzor obdržite pri sebi.","trace.desc":"TraceApp vam pomaga zabeležiti pot, razdaljo, hitrost in tempo ter podatke shranjuje najprej lokalno. Brez računa, brez vgrajenih analitičnih ali oglaševalskih SDK-jev tretjih oseb.","trace.feat.0":"Zabeležite in prikažite pot potovanja","trace.feat.1":"Statistika razdalje, hitrosti in tempa","trace.feat.2":"Predvajanje sledi in prikaz na zemljevidu","trace.feat.3":"Izbirno prepoznavanje stanja gibanja","trace.feat.4":"Zgodovino shranjuje v peskovniku naprave","trace.feat.5":"Izbirna sinhronizacija iCloud med napravami","trace.guide.0.t":"Dodelite dovoljenje za lokacijo","trace.guide.0.b":"Ob prvi uporabi po potrebi izberite dovoljenje za lokacijo »Med uporabo aplikacije« ali »Vedno«; dovoljenje lahko kadar koli spremenite v sistemskih nastavitvah.","trace.guide.1.t":"Začnite potovanje","trace.guide.1.b":"V aplikaciji začnite beleženje; pot, razdalja, hitrost in tempo se shranijo v trenutno napravo.","trace.guide.2.t":"Predvajajte in uredite","trace.guide.2.b":"V zgodovini si oglejte pot in statistiko, izbrišite vnose, ki jih ne potrebujete, ali izvozite prek sistemske skupne rabe (če aplikacija to omogoča).","trace.guide.3.t":"Vklopite iCloud po potrebi","trace.guide.3.b":"Za sinhronizacijo med lastnimi napravami sami vklopite iCloud v sistemu in aplikaciji; razvijalec ne pridobi vaših poverilnic ali vsebine iCloud.","app.tab.overview":"Predstavitev izdelka","app.tab.start":"Vodnik za začetek","app.tab.privacy":"Pravilnik o zasebnosti","app.tab.terms":"Pogoji uporabe","app.tab.support":"Tehnična podpora","app.cta.start":"Začni","app.cta.readPrivacy":"Preberi pravilnik o zasebnosti","app.shots":"Posnetki iz trgovine","app.faq":"Pogosta vprašanja","app.contactTitle":"Stopite v stik","app.contactQ":"Če imate vprašanja, nas kontaktirajte:","app.supportContact":"Še potrebujete pomoč? Pišite na {email}.","app.getInStore":"Prenesite {app} v {store}","app.legal.effective":"Datum začetka veljavnosti","app.legal.platform":"Podprta platforma","app.legal.appname":"Ime aplikacije","app.footerSlogan":"Predstavitev izdelka · Vodnik za začetek · Zasebnost in podpora","tt.ui.headerSub":"Snemanje sledi GPS · Pregled poti · Zasebnost na prvem mestu","tt.ui.ovTitle":"Povežite čas in kraj v svojo zgodbo","tt.ui.privTitle":"Zapisi so vaši, podatki prav tako","tt.ui.privBody":"Brez računa, brez oglasov ali sledenja tretjih oseb. Sledi privzeto ostanejo v napravi; varnostna kopija v iCloud je povsem izbirna in gre le v vašo zasebno zbirko podatkov Apple CloudKit.","tt.ui.guideTitle":"Začnite s prvo sledjo","tt.ui.galleryTitle":"Odkrijte TimeTrails skozi poti vsakega dne","tt.ui.desc.start":"Hitro začnite – od dovoljenja za lokacijo do ogleda dnevnih sledi.","tt.ui.desc.privacy":"Spoznajte, kako aplikacija obravnava lokacijo, gibanje in varnostno kopijo v iCloud.","tt.ui.desc.terms":"Pred uporabo te aplikacije preberite pogoje uporabe.","tt.ui.desc.support":"Pomaga vam brez težav zabeležiti in pregledati vsako pot.","tt.ui.faq.0.q":"Ali me TimeTrails ves čas lokalizira?","tt.ui.faq.0.a":"Snemanje nadzorujete vi in ga lahko kadar koli začasno ustavite. Lokacija sistema se uporablja le za lokalno snemanje sledi, podatki pa privzeto ostanejo v napravi.","tt.ui.faq.1.q":"Lokacija se ne beleži?","tt.ui.faq.1.a":"V «Nastavitve → Zasebnost in varnost → Lokacijske storitve» za TimeTrails izberite «Vedno» ter vklopite «Natančna lokacija» in osveževanje aplikacij v ozadju.","tt.ui.faq.2.q":"Kako obnovim varnostno kopijo iCloud?","tt.ui.faq.2.a":"Z istim Apple ID, vklopljenim iCloud in običajno povezavo lahko obnovite ali ročno sinhronizirate v razdelku «Varnostna kopija podatkov iCloud» v nastavitvah.","tt.ui.faq.3.q":"Kako popolnoma izbrišem podatke?","tt.ui.faq.3.a":"Lokalne podatke lahko izbrišete v nastavitvah aplikacije; če je vklopljena varnostna kopija iCloud, izbrišite tudi kopijo v oblaku.","trace.ui.headerSub":"Snemanje poti · Podatki pod nadzorom","trace.ui.ovTitle":"Naj vsaka pot pusti sled","trace.ui.privTitle":"Najprej lokalno, podatki pod nadzorom","trace.ui.privBody":"Brez računa, brez vgrajenih oglasov ali statistike tretjih oseb. Sledi privzeto ostanejo v trenutni napravi; sinhronizacija z iCloud se uporablja le, ko jo sami vklopite.","trace.ui.guideTitle":"Začnite s prvo potjo","trace.ui.galleryTitle":"Poti, zemljevid in zgodovina","trace.ui.desc.start":"Hitro začnite – od dovoljenja za lokacijo do pregleda poti.","trace.ui.desc.privacy":"Spoznajte, kako se obravnavajo podatki o sledeh, iCloud in sistemska dovoljenja.","trace.ui.desc.terms":"Pred uporabo te aplikacije preberite pogoje uporabe.","trace.ui.desc.support":"Pomaga vam brez težav zabeležiti in upravljati vsako pot.","trace.ui.faq.0.q":"Kako prilagodim dovoljenje za lokacijo?","trace.ui.faq.0.a":"V «Nastavitve → Zasebnost in varnost → Lokacijske storitve → TraceApp» izberite «Med uporabo aplikacije» ali «Vedno»; kadar koli lahko izklopite.","trace.ui.faq.1.q":"Kako izbrišem podatke?","trace.ui.faq.1.a":"V aplikaciji lahko izbrišete posamezne ali vse zapise; odstranitev izbriše lokalne podatke. Če je iCloud vklopljen, je treba sinhronizirano kopijo upravljati ločeno v iCloud.","trace.ui.faq.2.q":"Kaj naj priložim ob prijavi težave?","trace.ui.faq.2.a":"Priporočamo, da priložite korake za ponovitev, pričakovan in dejanski rezultat, model naprave in različico sistema; lahko dodate posnetke zaslona, ki pomagajo najti težavo.","mem.ui.headerSub":"Obletnice · Rojstni dnevi · Odštevanje","mem.ui.ovTitle":"Ustvarjeno za beleženje vsega pomembnega","mem.ui.privTitle":"Zasebnost pred udobjem","mem.ui.priv.ios":"Brez računa, brez oglasov, brez sledenja tretjih oseb; če je sinhronizacija vklopljena, gre le v vašo zasebno zbirko podatkov iCloud.","mem.ui.priv.hm":"Brez računa, brez povezave z omrežjem, brez varnostne kopije v oblaku; vaši zapisi ostanejo le v trenutni napravi.","mem.ui.guideTitle":"Začnite s prvim zapisom","mem.ui.galleryTitle":"Oglejte si dejanski vmesnik {app}","mem.ui.storeHint":"Poiščite «{app}» v {store} in prenesite to aplikacijo.","mem.ui.desc.start":"Hitro začnite uporabljati {app} – od prve stvaritve do dovoljenja za obvestila.","mem.ui.desc.privacy":"Preberite pravilnik o zasebnosti {app}, ki velja za platformo, ki jo uporabljate.","mem.ui.desc.terms":"Pred uporabo {app} preberite te pogoje uporabe.","mem.ui.desc.support":"Pomaga vam brez težav uporabljati {app}.","mem.ui.faq.0.q":"Ali se podatki sinhronizirajo z drugimi napravami?","mem.ui.faq.0.a.ios":"Ko se prijavite v iCloud in vklopite sinhronizacijo, se podatki prek vaše zasebne zbirke iCloud sinhronizirajo med iPhone, iPad in Apple Watch.","mem.ui.faq.0.a.hm":"Ne. Ta različica se ne povezuje z omrežjem in ne ponuja sinhronizacije v oblaku; podatki ostanejo le v trenutni napravi.","mem.ui.faq.1.q":"Kako izbrišem podatke?","mem.ui.faq.1.a.ios":"Zapise lahko izbrišete v aplikaciji; odstranitev izbriše lokalne podatke, podatke iCloud pa lahko upravljate v «Nastavitve → iCloud».","mem.ui.faq.1.a.hm":"Zapise lahko izbrišete v aplikaciji in izpraznite koš; odstranitev izbriše vse lokalne podatke.","mem.ui.faq.2.q":"Kaj storiti, če se opomnik ne prikaže?","mem.ui.faq.2.a":"Preverite, ali ima zapis nastavljen opomnik, in v sistemskih nastavitvah aplikaciji dovolite pošiljanje obvestil. Izklop obvestil vpliva le na opomnike, ne na same zapise.","mem.ui.pc.title":"Pomembne dni shranite v napravo, ki vam ustreza.","mem.ui.pc.desc":"Izberite platformo, ki jo uporabljate. Obe različici temeljita na lokalnih podatkih in odsotnosti sledenja tretjih oseb, razlikujeta pa se v sinhronizaciji, imenu aplikacije in veljavnih pogojih.","mem.ui.pc.ios.desc":"Podpira lokalne opomnike, gradnike, Apple Watch in izbirno zasebno sinhronizacijo prek iCloud.","mem.ui.pc.ios.cta":"Ogled različice za iOS","mem.ui.pc.hm.desc":"Povsem lokalna različica: brez omrežja, brez sinhronizacije v oblaku; podatki ostanejo le v peskovniku aplikacije v napravi.","mem.ui.pc.hm.cta":"Ogled različice za HarmonyOS"};export{e as default};
